package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseP4ConcurrencyTest extends PhaseP4Fixtures {
 static final String SCHEMA="qa_p4_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 Object result(Supplier<?> run){try{return run.get();}catch(RuntimeException e){return e;}}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return result(a);});var y=pool.submit(()->{start.await();return result(b);});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 @Test void concurrentFeedbackRetryCreatesOneVersionAndOneSubmissionEvent()throws Exception{UUID a=delivered();var in=input(a,1,true,false);var r=race(()->reputation.feedback(learner.id(),in),()->reputation.feedback(learner.id(),in));assertThat(r).allMatch(UUID.class::isInstance);assertThat(r.getFirst()).isEqualTo(r.getLast());assertThat(db.queryForObject("SELECT count(*) FROM clinic_feedback_versions WHERE feedback_id=?",Integer.class,r.getFirst())).isEqualTo(1);}
 @Test void editRacingPublicationCannotPublishTheNewUnreviewedVersion()throws Exception{UUID id=feedback();race(()->{reputation.review(reviewer.id(),reviewer.session(),id,new ProfessionalReputation.Review(1,"PUBLISH","A redacted synthetic appointment experience.",true,"PRIVACY_REDACTED"));return "reviewed";},()->reputation.feedback(learner.id(),new ProfessionalReputation.Feedback(appointment,1,1,"Synthetic amended private feedback",false,false,UUID.randomUUID())));assertThat(reputation.privateFeedback(learner.id(),learner.session(),id)).containsEntry("revision",2L).containsEntry("state","SUBMITTED");assertThat(reputation.publicFeedback(other.id(),author.id(),"TEXT")).isEmpty();}
 @Test void competingWeeklyReviewersPublishOneAuditedSelection()throws Exception{scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));LocalDate week=LocalDate.now(ZoneOffset.UTC).with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));UUID batch=reputation.proposeWeekly(issuer.id(),issuer.session(),"PSYCHOLOGIST","TEXT",week,"NEW_DISCOVERY");var second=PhaseIFixtures.member(db,users,tokens);role(second.id(),"CLINIC_REPUTATION_OPERATOR");db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",second.session());var results=race(()->{reputation.publishWeekly(reviewer.id(),reviewer.session(),batch);return "ok";},()->{reputation.publishWeekly(second.id(),second.session(),batch);return "ok";});assertThat(results.stream().filter("ok"::equals).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM clinic_weekly_feature_events WHERE batch_id=? AND action='INDEPENDENTLY_PUBLISHED'",Integer.class,batch)).isEqualTo(1);}
}
